mapper.select:
SELECT , , fw.warehouse_name AS fromWarehouseName, tw.warehouse_name AS toWarehouseName, fw.status AS fromWarehouseStatus, tw.status AS toWarehouseStatus, eu.nickname AS userName
t.is_deleted = 0
AND (t.transfer_no LIKE CONCAT('%', #{q.keyword}, '%') OR t.reason LIKE CONCAT('%', #{q.keyword}, '%') OR t.remark LIKE CONCAT('%', #{q.keyword}, '%') OR fw.warehouse_name LIKE CONCAT('%', #{q.keyword}, '%') OR tw.warehouse_name LIKE CONCAT('%', #{q.keyword}, '%') OR eu.nickname LIKE CONCAT('%', #{q.keyword}, '%'))
AND t.from_warehouse_id = #{q.fromWarehouseId}
AND t.to_warehouse_id = #{q.toWarehouseId}
AND (t.from_warehouse_id = #{q.warehouseId} OR t.to_warehouse_id = #{q.warehouseId})
AND t.transfer_type = #{q.transferType}
AND t.status = #{q.status}
AND t.user_id = #{q.userId}
AND t.create_time >= #{q.beginTime}
AND t.create_time <= #{q.endTime}
ORDER BY t.id DESC

SELECT i.id, i.sku_id, i.warehouse_id, i.stock, i.locked_stock, i.cost_price, (i.stock - i.locked_stock) AS availableStock, p.id AS productId, p.product_name AS productName, p.product_code AS productCode, sk.spec_text AS specText FROM shop_erp_inventory i INNER JOIN shop_product_sku sk ON sk.id = i.sku_id AND sk.is_deleted = 0 INNER JOIN shop_product p ON p.id = sk.product_id AND p.is_deleted = 0 WHERE i.is_deleted = 0 AND i.warehouse_id = #{warehouseId} AND i.stock - i.locked_stock > 0
AND (p.product_name LIKE CONCAT('%', #{keyword}, '%') OR p.product_code LIKE CONCAT('%', #{keyword}, '%') OR sk.spec_text LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY p.id DESC, i.id DESC LIMIT #{limit}
